/* Independent depth-ray regressions for the elevator's SVG visibility masks.
 * Run: node qa/audit-elevator-occlusion.cjs (no browser or packages required). */
const fs=require('node:fs'),vm=require('node:vm'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),ctx={window:{},console,addEventListener(){}};vm.createContext(ctx);
for(const f of ['core.js','elevator-occlusion.js'])vm.runInContext(fs.readFileSync(path.join(root,'dist',f),'utf8'),ctx);
const result=vm.runInContext(`(()=>{
const E=window.ElevatorOcclusion,tests=[];let checks=0;
function test(name,fn){try{fn();tests.push({name,ok:true})}catch(e){tests.push({name,ok:false,error:e.message})}}
function expect(x,message){if(!x)throw Error(message)}
function inside(p,poly){let sign=0;for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],c=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);if(Math.abs(c)<1e-7)continue;if(sign&&Math.sign(c)!==sign)return false;sign=Math.sign(c)}return true}
// A view ray starts in the projection plane and travels toward the viewer.
// Its largest box intersection t is the independently computed near surface.
function boxRay(p,b){const o=CR.map((x,i)=>x*p[0]/K3+CD[i]*p[1]/K3);let lo=-Infinity,hi=Infinity;
for(let i=0;i<3;i++){if(Math.abs(CV[i])<1e-9){if(o[i]<b[i]-1e-8||o[i]>b[i+3]+1e-8)return null}else{const a=(b[i]-o[i])/CV[i],c=(b[i+3]-o[i])/CV[i];lo=Math.max(lo,Math.min(a,c));hi=Math.min(hi,Math.max(a,c));if(lo>hi+1e-8)return null}}return hi}
const solids=[[41.5,15,41,42,39,65.5],[19.2,49.2,8.3,22.2,50.8,9.7],[33.8,49.2,28.3,36.8,50.8,29.7],[8,9,6.5,10,45,33.5],[0,0,5,3,54,113],[0,0,5,44,3,113],[0,0,109,29.1,54,114],[30.9,0,109,48,54,114]];
function verifyFaces(faces){const hidden=E.hiddenPolygons('target',faces,solids,{padding:0});for(const f of faces){const c=f[0].map((_,k)=>f.reduce((s,p)=>s+p[k],0)/f.length);for(let i=0;i<f.length;i++)for(const t of [.13,.49,.87]){const q=c.map((v,k)=>v*(1-t)+f[i][k]*t),p=P(...q),d=depthOf(q),hits=solids.map(b=>boxRay(p,b)).filter(v=>v!=null),near=hits.length?Math.max(...hits):-Infinity;if(Math.abs(near-d)<1e-4)continue;const expected=near>d+1e-5,actual=hidden.some(h=>inside(p,h));checks++;expect(actual===expected,'Ray mismatch at yaw '+YAW+' pitch '+PITCH+' point '+q+' near '+near+' target '+d)}}}
test('Rod masks match independent box-ray depths across 72 camera/state combinations',()=>{for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35,78]){setCam(yaw,pitch);E.begin();for(const [a,b,r]of[[[30,33,35.9],[30,33,114],.35],[[20,50,6],[20,50,108],.55],[[36,50,6],[36,50,108],.55]])verifyFaces(E.rodFaces(a,b,r))}});
test('Tall box masks match independent depths without center-depth ordering',()=>{for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35,78]){setCam(yaw,pitch);E.begin();verifyFaces(E.boxFaces(6,6,5,7.7,7.7,110));verifyFaces(E.boxFaces(21,48.6,7,35,52,8.5))}});
test('Closed second-floor door masks a rope locally, not by its long-segment centre',()=>{setCam(0,35);E.begin();const a=[30,33,35.9],b=[30,33,114],r=.35,door=[41.5,27,41,42,39,65.5],hidden=E.hiddenPolygons('cable',E.rodFaces(a,b,r),[door],{padding:0});expect(hidden.some(h=>inside(P(30.35,33,45),h)),'Cable should be hidden by second floor');expect(!hidden.some(h=>inside(P(30.35,33,100),h)),'Unobstructed upper cable removed')});
test('Guide shoe masks the local rail even when the rail centre is nearer',()=>{setCam(90,35);E.begin();const rail=E.rodFaces([20,50,6],[20,50,108],.55),shoe=[19.2,49.2,8.3,22.2,50.8,9.7],h=E.hiddenPolygons('rail',rail,[shoe],{padding:0});expect(h.some(q=>inside(P(20,50.55,9),q)),'Rail leaks through guide shoe');expect(!h.some(q=>inside(P(20,50.55,60),q)),'Clear rail incorrectly removed')});
test('A farther overlapping box never masks a nearer rod',()=>{setCam(0,35);E.begin();const faces=E.rodFaces([30,33,35.9],[30,33,114],.35),h=E.hiddenPolygons('cable',faces,[[10,25,20,11,40,115]],{padding:0});expect(h.length===0,'Far geometry masks nearer rod')});
test('Artwork stays unchanged inside one mask, with no synthetic strip strokes',()=>{setCam(0,35);setLight(105);E.begin();const a=[30,33,35.9],b=[30,33,114],raw=rod(a,b,.35,DARK,toneI,.25),out=E.maskRod('cable',a,b,.35,raw,[[41.5,27,41,42,39,65.5]]);expect(out.endsWith(raw+'</g>'),'Original SVG changed');expect((out.match(/stroke-width=/g)||[]).length===(raw.match(/stroke-width=/g)||[]).length,'New stroke introduced');expect(!/NaN|Infinity|undefined/.test(out),'Invalid SVG');const boxBounds=[6,6,5,7.7,7.7,110];expect(E.maskBox('self',boxBounds,'unchanged',[boxBounds])==='unchanged','Box masks itself')});
test('Explicit solid registration replaces stale geometry and reset clears frame',()=>{E.begin();E.addSolid('door',E.boxFaces(40,15,41,41,39,65));E.addSolid('door',E.boxFaces(40,15,41,41,20,65));expect(E.solids.length===1,'Duplicate solid registration');E.begin();expect(E.solids.length===0,'Stale solids survive begin')});
return {tests,rayComparisons:checks};})()`,ctx);
console.log(JSON.stringify(result,null,2));fs.writeFileSync(path.join(__dirname,'elevator-occlusion-results.json'),JSON.stringify(result,null,2)+'\n');assert(result.tests.every(t=>t.ok),'Occlusion regression failed');
